<template><OperationsFrame title="运行监控"><template #actions><div class="monitor-head"><span class="operations-caption">{{data.checkedAt?`最近检查：${data.checkedAt}`:''}}</span><el-button icon="Refresh" :loading="loading" @click="load">刷新</el-button></div></template>
 <div v-loading="loading"><div class="operations-grid"><el-card v-for="(name,key) in serviceNames" :key="key" class="operations-card"><template #header>{{name}}</template><el-tag :type="data.services?.[key]?.status==='UP'?'success':'danger'">{{data.services?.[key]?.status==='UP'?'正常':data.services?'不可用':'待检查'}}</el-tag><p class="operations-caption">{{data.services?.[key]?.message|| (data.services?.[key]?.latencyMs!=null?`响应 ${data.services[key].latencyMs} ms`:'服务运行状态')}}</p></el-card></div>
 <div class="operations-grid"><el-card class="operations-card"><template #header>CPU</template><el-progress type="dashboard" :percentage="percent((data.server?.cpu?.used||0)+(data.server?.cpu?.sys||0))" /><p class="operations-caption">{{data.server?.cpu?.cpuNum||'—'}} 个逻辑处理器</p></el-card><el-card class="operations-card"><template #header>物理内存</template><el-progress type="dashboard" :percentage="percent(data.server?.mem?.usage)" /><p class="operations-caption">已用 {{data.server?.mem?.used??'—'}} / {{data.server?.mem?.total??'—'}} GB</p></el-card><el-card class="operations-card"><template #header>Java 内存</template><el-progress type="dashboard" :percentage="percent(data.server?.jvm?.usage)" /><p class="operations-caption">已用 {{data.server?.jvm?.used??'—'}} / {{data.server?.jvm?.total??'—'}} MB</p></el-card></div>
 <GpuMonitorPanel :snapshot="data.gpu"/>
 <el-card class="operations-section"><template #header>服务器信息</template><el-descriptions :column="2" border><el-descriptions-item label="操作系统">{{data.server?.sys?.osName||'—'}} / {{data.server?.sys?.osArch||'—'}}</el-descriptions-item><el-descriptions-item label="Java版本">{{data.server?.jvm?.version||'—'}}</el-descriptions-item><el-descriptions-item label="运行时间">{{data.server?.jvm?.runTime||'—'}}</el-descriptions-item><el-descriptions-item label="自动刷新">{{data.refreshSeconds||30}} 秒</el-descriptions-item></el-descriptions></el-card>
 <el-card class="operations-section"><template #header>磁盘使用</template><el-table :data="data.server?.sysFiles||[]"><el-table-column prop="dirName" label="挂载目录" min-width="220" /><el-table-column prop="typeName" label="类型" width="120" /><el-table-column prop="total" label="总量" width="120" /><el-table-column prop="used" label="已用" width="120" /><el-table-column prop="free" label="可用" width="120" /><el-table-column label="使用率" min-width="160"><template #default="{row}"><el-progress :percentage="percent(row.usage)" /></template></el-table-column></el-table></el-card>
 <el-card class="operations-section"><template #header>实时数据连接</template><el-table :data="data.connectors||[]"><el-table-column prop="connectorName" label="连接名称" min-width="160" /><el-table-column prop="fieldName" label="所属井场" min-width="140" /><el-table-column label="协议" width="140"><template #default="{row}">{{sourceLabels[row.connectorType]||row.connectorType}}</template></el-table-column><el-table-column prop="status" label="接入状态" width="130" /><el-table-column prop="lastHeartbeat" label="最后心跳" width="180" /><el-table-column label="异常记录" width="110"><template #default="{row}"><el-tag :type="row.hasError?'danger':'info'">{{row.hasError?'有':'无'}}</el-tag></template></el-table-column></el-table></el-card>
 <el-card class="operations-section"><template #header>预测与模型更新任务</template><el-table :data="data.tasks||[]"><el-table-column label="类型"><template #default="{row}">{{row.taskType==='PREDICTION'?'预测任务':'模型增量更新'}}</template></el-table-column><el-table-column prop="status" label="状态" /><el-table-column prop="count" label="数量" /></el-table></el-card></div>
</OperationsFrame></template>
<script setup>
import GpuMonitorPanel from './GpuMonitorPanel.vue'
import {ref,onMounted,onBeforeUnmount,onActivated,onDeactivated} from 'vue';import OperationsFrame from './OperationsFrame.vue';import {listOperation,getReferenceDictionary} from '@/api/operations';
const data=ref({}),loading=ref(false),sourceLabels=ref({}),serviceNames={java:'Java 业务服务',database:'MySQL 数据库',algorithm:'Python 算法服务'};let timer,active=true
const percent=n=>Math.min(100,Math.max(0,Math.round(Number(n)||0)))
function schedule(){window.clearTimeout(timer);if(active)timer=window.setTimeout(()=>{if(!document.hidden)load();else schedule()},(data.value.refreshSeconds||30)*1000)}
async function load(){if(loading.value)return;loading.value=true;try{data.value=(await listOperation('monitor')).data}catch{}finally{loading.value=false;schedule()}}
onMounted(async()=>{await load();try{const r=await getReferenceDictionary('drilling_data_source');sourceLabels.value=Object.fromEntries(r.data.map(x=>[x.dictValue,x.dictLabel]))}catch{}});onActivated(()=>{active=true;schedule()});onDeactivated(()=>{active=false;window.clearTimeout(timer)});onBeforeUnmount(()=>{active=false;window.clearTimeout(timer)})
</script>
